/**
 * CATÁLOGO DE CONCEITOS do OBJETO FALADO (pt-BR + inglês + um pouco de espanhol).
 * Cada linha: id, palavras (sem acento; frases de várias palavras valem), categoria, arquétipo + parâmetros,
 * 3 cores (principal, secundária, detalhe), comportamentos padrão e função na vila.
 *   c('cachorro', 'cachorro cao dog', 'animal', 'quad', {ears:'floppy'}, 'tan cream chocolate', 'walks follows sound:woof')
 * Comportamentos: "tipo" ou "tipo:kind" ou "tipo:kind@força" (força 0..1).
 */
import { BEHAVIORS, type BehType, type ColorName, type ObjBehavior } from '../cavaspec';
import type { Opts } from './builders';

export type Cat = 'animal' | 'bird' | 'sea' | 'bug' | 'fantasy' | 'vehicle' | 'air' | 'water' | 'building' | 'play' | 'furniture' | 'food' | 'nature' | 'robot' | 'machine' | 'toy' | 'thing';
export type Fn = 'bridge' | 'stairs' | 'ramp' | 'slide' | 'trampoline' | 'pump' | 'boat' | 'crane' | 'lamp' | 'shelter' | 'wall' | 'tower';
export interface Concept {
  id: string;
  words: string[];
  cat: Cat;
  build: string;
  o: Opts;
  col: [ColorName, ColorName, ColorName];
  beh: ObjBehavior[];
  fn?: Fn;
  /** forma comprida que pode virar "casco" de veículo ("barco de banana") */
  hull?: boolean;
  /** objeto parado (construção) */
  fixed?: boolean;
}

export function parseBeh(s: string): ObjBehavior[] {
  const out: ObjBehavior[] = [];
  for (const tok of s.split(/\s+/).filter(Boolean)) {
    const [head, pw] = tok.split('@');
    const [type, kind] = head.split(':') as [BehType, string | undefined];
    if (!(type in BEHAVIORS)) continue;
    const b: ObjBehavior = { type, power: pw ? Number(pw) : 0.5 };
    const kinds = BEHAVIORS[type] as readonly string[];
    if (kinds.length) b.kind = kind && kinds.includes(kind) ? kind : kinds[0];
    out.push(b);
  }
  return out;
}

export const CONCEPTS: Concept[] = [];
const IDS = new Set<string>();
function c(id: string, words: string, cat: Cat, build: string, o: Opts, col: string, beh = '', extra: Partial<Pick<Concept, 'fn' | 'hull' | 'fixed'>> = {}): void {
  if (IDS.has(id)) throw new Error('conceito repetido: ' + id);
  IDS.add(id);
  const cs = col.split(/\s+/) as ColorName[];
  CONCEPTS.push({ id, words: [...new Set([id.replace(/_/g, ' '), ...words.split(',').map((w) => w.trim()).filter(Boolean)])], cat, build, o, col: [cs[0], cs[1] ?? cs[0], cs[2] ?? cs[1] ?? cs[0]], beh: parseBeh(beh), ...extra });
}
const A = 'walks follows';
const LAND = 'rolls ride';

